CREATE TABLE intercom_recordings (id VARCHAR(36) PRIMARY KEY, space_id VARCHAR(36) NOT NULL, case_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, object_key VARCHAR(500) NOT NULL UNIQUE, source_content_type VARCHAR(100) NOT NULL, final_content_type VARCHAR(100) NOT NULL, byte_size BIGINT NOT NULL, started_at VARCHAR(40) NOT NULL, ended_at VARCHAR(40) NOT NULL, transcription_status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL, failed_reason TEXT NULL, CONSTRAINT fk_intercom_recordings_space FOREIGN KEY (space_id) REFERENCES collaboration_spaces(id) ON DELETE CASCADE, CONSTRAINT fk_intercom_recordings_case FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE, CONSTRAINT fk_intercom_recordings_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT chk_intercom_recordings_status CHECK (transcription_status IN ('queued','processing','completed','failed')), CONSTRAINT chk_intercom_recordings_size CHECK (byte_size > 0));
-- statement-break
CREATE INDEX idx_intercom_recordings_space_created ON intercom_recordings(space_id, created_at);
